import pandas as pd
import numpy as np

df = pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)

missing_markers = {'', 'nan', 'NaN', 'NA', 'N/A', 'null', 'None', 'NONE'}

rows_missing = 0
for idx, row in df.iterrows():
    if any((pd.isna(v)) or (str(v).strip() in missing_markers) for v in row):
        rows_missing += 1

print('rows missing (string scan)', rows_missing)

# find any non-empty markers that look like missing
candidates = set()
for col in df.columns:
    vals = df[col].dropna().astype(str).str.strip().unique()
    for v in vals:
        if v.lower() in {'nan','na','n/a','null','none','-999','-99','9999'}:
            candidates.add(v)
print('missing-like markers found', candidates)
